  1→import { useState, useCallback, useEffect } from "react";
  2→import type {
  3→  ActionFunctionArgs,
  4→  HeadersFunction,
  5→  LoaderFunctionArgs,
  6→} from "react-router";
  7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
  8→import { useAppBridge } from "@shopify/app-bridge-react";
  9→import { authenticate } from "../shopify.server";
 10→import { boundary } from "@shopify/shopify-app-react-router/server";
 11→import { getShopSubscription } from "../billing.server";
 12→import { PLAN_LIMITS, UNLIMITED } from "../plans";
 13→import db from "../db.server";
 14→import { sendTestEmail } from "../email.server";
 15→import {
 16→  Page,
 17→  Layout,
 18→  Card,
 19→  BlockStack,
 20→  InlineStack,
 21→  Text,
 22→  Badge,
 23→  Button,
 24→  Divider,
 25→  Box,
 26→  Select,
 27→  TextField,
 28→  Banner,
 29→} from "@shopify/polaris";
 30→
 31→// ---------------------------------------------------------------------------
 32→// Loader
 33→// ---------------------------------------------------------------------------
 34→
 35→export const loader = async ({ request }: LoaderFunctionArgs) => {
 36→  const { session, admin } = await authenticate.admin(request);
 37→  const shop = session.shop;
 38→
 39→  const [subscription, zipCount, shopSettings, shopResponse] = await Promise.all([
 40→    getShopSubscription(shop),
 41→    db.zipCode.count({ where: { shop } }),
 42→    db.shopSettings.findUnique({ where: { shop } }),
 43→    admin.graphql(`{ shop { name } }`),
 44→  ]);
 45→
 46→  const shopData = await shopResponse.json();
 47→  const shopName: string = shopData.data?.shop?.name ?? shop.replace(".myshopify.com", "");
 48→
 49→  // Cache the shop display name so email service can use it without API calls
 50→  await db.shopSettings.upsert({
 51→    where: { shop },
 52→    create: { shop, shopName },
 53→    update: { shopName },
 54→  });
 55→
 56→  return {
 57→    subscription,
 58→    zipCount,
 59→    shop,
 60→    shopName,
 61→    defaultBehavior: shopSettings?.defaultBehavior ?? "block",
 62→    notificationEmail: shopSettings?.notificationEmail ?? "",
 63→    emailSenderName: shopSettings?.emailSenderName ?? "",
 64→    emailReplyTo: shopSettings?.emailReplyTo ?? "",
 65→  };
 66→};
 67→
 68→// ---------------------------------------------------------------------------
 69→// Action
 70→// ---------------------------------------------------------------------------
 71→
 72→export const action = async ({ request }: ActionFunctionArgs) => {
 73→  const { session } = await authenticate.admin(request);
 74→  const shop = session.shop;
 75→
 76→  const formData = await request.formData();
 77→  const intent = formData.get("intent") as string;
 78→
 79→  try {
 80→    if (intent === "save-behavior") {
 81→      const defaultBehavior = formData.get("defaultBehavior") as string;
 82→      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
 83→        return { error: "Invalid value for defaultBehavior" };
 84→      }
 85→      await db.shopSettings.upsert({
 86→        where: { shop },
 87→        create: { shop, defaultBehavior },
 88→        update: { defaultBehavior },
 89→      });
 90→      return { success: true, intent };
 91→    }
 92→
 93→    if (intent === "save-notification") {
 94→      const notificationEmail =
 95→        (formData.get("notificationEmail") as string | null) ?? "";
 96→      await db.shopSettings.upsert({
 97→        where: { shop },
 98→        create: { shop, notificationEmail: notificationEmail || null },
 99→        update: { notificationEmail: notificationEmail || null },
100→      });
101→      return { success: true, intent };
102→    }
103→
104→    if (intent === "save-email-settings") {
105→      const emailSenderName =
106→        (formData.get("emailSenderName") as string | null)?.trim() || null;
107→      const emailReplyTo =
108→        (formData.get("emailReplyTo") as string | null)?.trim() || null;
109→      await db.shopSettings.upsert({
110→        where: { shop },
111→        create: { shop, emailSenderName, emailReplyTo },
112→        update: { emailSenderName, emailReplyTo },
113→      });
114→      return { success: true, intent };
115→    }
116→
117→    if (intent === "send-test-email") {
118→      const testEmail = (formData.get("testEmail") as string | null) ?? "";
119→      if (!testEmail) return { error: "No email address provided." };
120→      const settings = await db.shopSettings.findUnique({ where: { shop } });
121→      const sent = await sendTestEmail(
122→        testEmail,
123→        { senderName: settings?.emailSenderName, shopDisplayName: settings?.shopName, replyTo: settings?.emailReplyTo },
124→        shop,
125→      );
126→      return sent
127→        ? { success: true, intent }
128→        : { error: "Failed to send test email. Check your Resend API key and sender email." };
129→    }
130→
131→    return { error: "Unknown intent" };
132→  } catch {
133→    return { error: "Failed to save settings. Please try again." };
134→  }
135→};
