137→// ---------------------------------------------------------------------------
138→// Component
139→// ---------------------------------------------------------------------------
140→
141→export default function SettingsPage() {
142→  const { subscription, zipCount, shop, shopName, defaultBehavior, notificationEmail, emailSenderName, emailReplyTo } =
143→    useLoaderData<typeof loader>();
144→  const navigate = useNavigate();
145→  const shopify = useAppBridge();
146→  const limits = PLAN_LIMITS[subscription.planTier];
147→
148→  // Fetchers — one per save section so loading states stay independent
149→  const behaviorFetcher = useFetcher<typeof action>();
150→  const notificationFetcher = useFetcher<typeof action>();
151→  const emailSettingsFetcher = useFetcher<typeof action>();
152→  const testEmailFetcher = useFetcher<typeof action>();
153→
154→  // Local controlled state
155→  const [behaviorValue, setBehaviorValue] = useState(defaultBehavior);
156→  const [emailValue, setEmailValue] = useState(notificationEmail);
157→  const [senderNameValue, setSenderNameValue] = useState(emailSenderName);
158→  const [replyToValue, setReplyToValue] = useState(emailReplyTo);
159→
160→  const isSavingBehavior = behaviorFetcher.state !== "idle";
161→  const isSavingNotification = notificationFetcher.state !== "idle";
162→  const isSavingEmailSettings = emailSettingsFetcher.state !== "idle";
163→  const isSaving = isSavingBehavior || isSavingNotification || isSavingEmailSettings;
164→
165→  // Track dirty state
166→  const isDirty =
167→    behaviorValue !== defaultBehavior ||
168→    emailValue !== notificationEmail ||
169→    senderNameValue !== emailSenderName ||
170→    replyToValue !== emailReplyTo;
171→
172→  // Toast on success
173→  useEffect(() => {
174→    if (
175→      behaviorFetcher.data &&
176→      "success" in behaviorFetcher.data &&
177→      behaviorFetcher.data.success
178→    ) {
179→      shopify.toast.show("Settings saved");
180→    }
181→  }, [behaviorFetcher.data, shopify]);
182→
183→  useEffect(() => {
184→    if (
185→      notificationFetcher.data &&
186→      "success" in notificationFetcher.data &&
187→      notificationFetcher.data.success
188→    ) {
189→      shopify.toast.show("Settings saved");
190→    }
191→  }, [notificationFetcher.data, shopify]);
192→
193→  useEffect(() => {
194→    if (
195→      emailSettingsFetcher.data &&
196→      "success" in emailSettingsFetcher.data &&
197→      emailSettingsFetcher.data.success
198→    ) {
199→      shopify.toast.show("Email settings saved");
200→    }
201→  }, [emailSettingsFetcher.data, shopify]);
202→
203→  useEffect(() => {
204→    if (
205→      testEmailFetcher.data &&
206→      "success" in testEmailFetcher.data &&
207→      testEmailFetcher.data.success
208→    ) {
209→      shopify.toast.show("Test email sent!");
210→    }
211→  }, [testEmailFetcher.data, shopify]);
212→
213→  const handleBehaviorChange = useCallback(
214→    (value: string) => setBehaviorValue(value),
215→    [],
216→  );
217→
218→  const handleEmailChange = useCallback(
219→    (value: string) => setEmailValue(value),
220→    [],
221→  );
222→
223→  const handleSaveAll = useCallback(() => {
224→    if (behaviorValue !== defaultBehavior) {
225→      const fd = new FormData();
226→      fd.append("intent", "save-behavior");
227→      fd.append("defaultBehavior", behaviorValue);
228→      behaviorFetcher.submit(fd, { method: "post" });
229→    }
230→    if (emailValue !== notificationEmail) {
231→      const fd = new FormData();
232→      fd.append("intent", "save-notification");
233→      fd.append("notificationEmail", emailValue);
234→      notificationFetcher.submit(fd, { method: "post" });
235→    }
236→    if (senderNameValue !== emailSenderName || replyToValue !== emailReplyTo) {
237→      const fd = new FormData();
238→      fd.append("intent", "save-email-settings");
239→      fd.append("emailSenderName", senderNameValue);
240→      fd.append("emailReplyTo", replyToValue);
241→      emailSettingsFetcher.submit(fd, { method: "post" });
242→    }
243→  }, [behaviorFetcher, notificationFetcher, emailSettingsFetcher, behaviorValue, emailValue, senderNameValue, replyToValue, defaultBehavior, notificationEmail, emailSenderName, emailReplyTo]);
244→
245→  const handleDiscard = useCallback(() => {
246→    setBehaviorValue(defaultBehavior);
247→    setEmailValue(notificationEmail);
248→    setSenderNameValue(emailSenderName);
249→    setReplyToValue(emailReplyTo);
250→  }, [defaultBehavior, notificationEmail, emailSenderName, emailReplyTo]);
251→
252→  const handleSendTestEmail = useCallback(() => {
253→    if (!emailValue) return;
254→    const fd = new FormData();
255→    fd.append("intent", "send-test-email");
256→    fd.append("testEmail", emailValue);
257→    testEmailFetcher.submit(fd, { method: "post" });
258→  }, [emailValue, testEmailFetcher]);
259→
260→  const behaviorOptions = [
261→    {
262→      label: "Block — show 'not available' message (recommended)",
263→      value: "block",
264→    },
265→    {
266→      label: "Allow — treat as available (for stores with broad coverage)",
267→      value: "allow",
268→    },
269→  ];
270→
271→  const planBadgeTone =
272→    subscription.planTier === "ultimate"
273→      ? ("success" as const)
274→      : subscription.planTier === "pro"
275→        ? ("info" as const)
276→        : subscription.planTier === "starter"
277→          ? ("attention" as const)
278→          : ("new" as const);
279→
280→  const planLabel = limits.label;
281→
282→  return (
283→    <Page
284→      title="Settings"
285→      subtitle="Manage your app settings and subscription"
286→      backAction={{ onAction: () => navigate("/app") }}
287→      primaryAction={isDirty ? {
288→        content: "Save",
289→        onAction: handleSaveAll,
290→        loading: isSaving,
291→      } : undefined}
292→      secondaryActions={isDirty ? [{
293→        content: "Discard",
294→        onAction: handleDiscard,
295→      }] : []}
296→    >
297→      <Box paddingBlockEnd="1600">
298→        <Layout>
299→
300→          {/* ----------------------------------------------------------------
301→              Section 1: Subscription
302→          ---------------------------------------------------------------- */}
303→          <Layout.Section>
304→            <Card>
305→              <BlockStack gap="400">
306→                <Text as="h2" variant="headingMd">
307→                  Subscription
308→                </Text>
309→                <Divider />
310→                <InlineStack align="space-between" blockAlign="center">
311→                  <BlockStack gap="100">
312→                    <Text as="p" variant="bodyMd">
313→                      Current Plan
314→                    </Text>
315→                    <InlineStack gap="200" blockAlign="center">
316→                      <Badge tone={planBadgeTone}>{`${planLabel} Plan`}</Badge>
317→                      {subscription.planTier !== "free" && (
318→                        <Text as="span" tone="subdued" variant="bodySm">
319→                          {subscription.billingInterval === "annual"
320→                            ? "Billed annually"
321→                            : "Billed monthly"}
322→                        </Text>
323→                      )}
324→                      {(subscription.planTier === "free" || subscription.planTier === "starter") && (
325→                        <Text as="span" tone="subdued" variant="bodySm">
326→                          {subscription.planTier === "free" ? "Limited features" : "Essential features"}
327→                        </Text>
328→                      )}
329→                    </InlineStack>
330→                  </BlockStack>
331→                  <Button
332→                    variant="primary"
333→                    onClick={() => navigate("/app/pricing")}
334→                  >
335→                    {subscription.planTier === "free" || subscription.planTier === "starter"
336→                      ? "Upgrade Plan"
337→                      : "Manage Plan"}
338→                  </Button>
339→                </InlineStack>
340→              </BlockStack>
341→            </Card>
342→          </Layout.Section>
343→
344→          {/* ----------------------------------------------------------------
345→              Section 2: Default Behavior for Unknown Zip Codes (NEW)
346→          ---------------------------------------------------------------- */}
347→          <Layout.Section>
348→            <Card>
349→              <BlockStack gap="400">
350→                <BlockStack gap="100">
351→                  <Text as="h2" variant="headingMd">
352→                    Default Behavior for Unknown Zip Codes
353→                  </Text>
354→                  <Text as="p" tone="subdued" variant="bodyMd">
355→                    Choose what happens when a customer enters a zip code that
356→                    is not in your list.
357→                  </Text>
358→                </BlockStack>
359→                <Divider />
360→                {behaviorFetcher.data &&
361→                  "error" in behaviorFetcher.data &&
362→                  behaviorFetcher.data.error && (
363→                    <Banner tone="critical">
364→                      {behaviorFetcher.data.error}
365→                    </Banner>
366→                  )}
367→                <Select
368→                  label="Behavior for unlisted zip codes"
369→                  options={behaviorOptions}
370→                  value={behaviorValue}
371→                  onChange={handleBehaviorChange}
372→                />
373→                <Text as="p" tone="subdued" variant="bodySm">
374→                  This only applies to zip codes not in your list. Explicitly
375→                  blocked zip codes are always blocked.
376→                </Text>
377→              </BlockStack>
378→            </Card>
379→          </Layout.Section>
380→
381→          {/* ----------------------------------------------------------------
382→              Section 3: Notifications (NEW)
383→          ---------------------------------------------------------------- */}
384→          <Layout.Section>
385→            <Card>
386→              <BlockStack gap="400">
387→                <BlockStack gap="100">
388→                  <Text as="h2" variant="headingMd">
389→                    Waitlist Notifications
390→                  </Text>
391→                  <Text as="p" tone="subdued" variant="bodyMd">
392→                    Get notified by email when customers join the waitlist.
393→                  </Text>
394→                </BlockStack>
395→                <Divider />
396→                {notificationFetcher.data &&
397→                  "error" in notificationFetcher.data &&
398→                  notificationFetcher.data.error && (
399→                    <Banner tone="critical">
400→                      {notificationFetcher.data.error}
401→                    </Banner>
402→                  )}
403→                {testEmailFetcher.data &&
404→                  "error" in testEmailFetcher.data &&
405→                  testEmailFetcher.data.error && (
406→                    <Banner tone="critical">
407→                      {testEmailFetcher.data.error}
408→                    </Banner>
409→                  )}
410→                <TextField
411→                  label="Notification email"
412→                  type="email"
413→                  placeholder="your@email.com"
414→                  value={emailValue}
415→                  onChange={handleEmailChange}
416→                  autoComplete="email"
417→                />
418→                <Text as="p" tone="subdued" variant="bodySm">
419→                  If left empty, no email notifications are sent.
420→                </Text>
421→                <Button
422→                  onClick={handleSendTestEmail}
423→                  loading={testEmailFetcher.state !== "idle"}
424→                  disabled={!emailValue}
425→                >
426→                  Send Test Email
427→                </Button>
428→              </BlockStack>
429→            </Card>
430→          </Layout.Section>
431→
432→          {/* ----------------------------------------------------------------
433→              Section 4: Email Sender Settings
434→          ---------------------------------------------------------------- */}
435→          <Layout.Section>
436→            <Card>
437→              <BlockStack gap="400">
438→                <BlockStack gap="100">
439→                  <Text as="h2" variant="headingMd">
440→                    Email Sender Settings
441→                  </Text>
442→                  <Text as="p" tone="subdued" variant="bodyMd">
443→                    Configure how outgoing emails appear to your customers.
444→                  </Text>
445→                </BlockStack>
446→                <Divider />
447→                {emailSettingsFetcher.data &&
448→                  "error" in emailSettingsFetcher.data &&
449→                  emailSettingsFetcher.data.error && (
450→                    <Banner tone="critical">
451→                      {emailSettingsFetcher.data.error}
452→                    </Banner>
453→                  )}
454→                <TextField
455→                  label="Sender name"
456→                  value={senderNameValue}
457→                  onChange={setSenderNameValue}
458→                  placeholder={shopName}
459→                  autoComplete="off"
460→                  helpText={`Customers see this in the "From" field. Leave blank to use your store name. Emails are sent as "${senderNameValue.trim() || shopName} via Pinzo <noreply@boldteq.app>".`}
461→                />
462→                <TextField
463→                  label="Reply-to email"
464→                  type="email"
465→                  value={replyToValue}
466→                  onChange={setReplyToValue}
467→                  placeholder="support@yourstore.com"
468→                  autoComplete="email"
469→                  helpText="When customers reply to an email, their reply goes to this address. Leave blank for no reply-to."
470→                />
471→                <Box
472→                  padding="300"
473→                  background="bg-surface-secondary"
474→                  borderRadius="200"
475→                >
476→                  <BlockStack gap="100">
477→                    <Text as="p" variant="bodySm" fontWeight="semibold">
478→                      Preview
479→                    </Text>
480→                    <Text as="p" variant="bodySm" tone="subdued">
481→                      From: {senderNameValue.trim() || shopName} via Pinzo &lt;noreply@boldteq.app&gt;
482→                    </Text>
483→                    <Text as="p" variant="bodySm" tone="subdued">
484→                      Reply-To: {replyToValue.trim() || "Not set — replies will not be delivered"}
485→                    </Text>
486→                  </BlockStack>
487→                </Box>
488→              </BlockStack>
489→            </Card>
490→          </Layout.Section>
491→
492→          {/* ----------------------------------------------------------------
493→              Section 5: Usage & Limits
494→          ---------------------------------------------------------------- */}
495→          <Layout.Section>
496→            <Card>
497→              <BlockStack gap="400">
498→                <Text as="h2" variant="headingMd">
499→                  Usage &amp; Limits
500→                </Text>
501→                <Divider />
502→                <InlineStack align="space-between">
503→                  <Text as="p" variant="bodyMd">
504→                    Zip Codes Used
505→                  </Text>
506→                  <Text as="p" fontWeight="semibold">
507→                    {zipCount}
508→                    {limits.maxZipCodes < UNLIMITED
509→                      ? ` / ${limits.maxZipCodes}`
510→                      : " (Unlimited)"}
511→                  </Text>
512→                </InlineStack>
513→                <InlineStack align="space-between">
514→                  <Text as="p" variant="bodyMd">
515→                    Blocked Zip Codes
516→                  </Text>
517→                  <Text as="p" fontWeight="semibold">
518→                    {limits.allowBlocked ? "Enabled" : "Not Available"}
519→                  </Text>
520→                </InlineStack>
521→                <InlineStack align="space-between">
522→                  <Text as="p" variant="bodyMd">
523→                    Delivery Rules
524→                  </Text>
525→                  <Text as="p" fontWeight="semibold">
526→                    {limits.maxDeliveryRules >= UNLIMITED
527→                      ? "Unlimited"
528→                      : limits.maxDeliveryRules === 0
529→                        ? "Not Available"
530→                        : `Up to ${limits.maxDeliveryRules}`}
531→                  </Text>
532→                </InlineStack>
533→                <InlineStack align="space-between">
534→                  <Text as="p" variant="bodyMd">
535→                    Waitlist
536→                  </Text>
537→                  <Text as="p" fontWeight="semibold">
538→                    {limits.maxWaitlist >= UNLIMITED
539→                      ? "Unlimited"
540→                      : limits.maxWaitlist === 0
541→                        ? "Not Available"
542→                        : `Up to ${limits.maxWaitlist} entries`}
543→                  </Text>
544→                </InlineStack>
545→                <InlineStack align="space-between">
546→                  <Text as="p" variant="bodyMd">
547→                    Store
548→                  </Text>
549→                  <Text as="p" fontWeight="semibold">
550→                    {shop}
551→                  </Text>
552→                </InlineStack>
553→              </BlockStack>
554→            </Card>
555→          </Layout.Section>
556→
557→          {/* ----------------------------------------------------------------
558→              Section 5: Data Management (NEW)
559→          ---------------------------------------------------------------- */}
560→          <Layout.Section>
561→            <Card>
562→              <BlockStack gap="400">
563→                <Text as="h2" variant="headingMd">
564→                  Data Management
565→                </Text>
566→                <Divider />
567→                <InlineStack gap="300" wrap>
568→                  <Button onClick={() => navigate("/app/zip-codes")}>
569→                    Manage Zip Codes
570→                  </Button>
571→                  <Button onClick={() => navigate("/app/waitlist")}>
572→                    View Waitlist
573→                  </Button>
574→                  <Button onClick={() => navigate("/app/delivery-rules")}>
575→                    Manage Delivery Rules
576→                  </Button>
577→                </InlineStack>
578→              </BlockStack>
579→            </Card>
580→          </Layout.Section>
581→
582→        </Layout>
583→      </Box>
584→    </Page>
585→  );
586→}
587→
588→export function ErrorBoundary() {
589→  return boundary.error(useRouteError());
590→}
591→
592→export const headers: HeadersFunction = (headersArgs) => {
593→  return boundary.headers(headersArgs);
594→};
